import { curandera, postera, talabartero } from './personas-salta3.mjs';
import { almacen as almacenE, curanderaCasa, talabarteria } from './edificios.mjs';
import { suelo } from './catalogo-35.mjs';
import { moneda } from './catalogo-29.mjs';
import { feriante } from './personas-salta3.mjs';
import { pocha, peona, mielera, pescador } from './personas-corrientes.mjs';
import { arrieroJ, tejedora, salinero, fidel } from './personas-jujuy.mjs';
import { curanderaSalta, postaCorrientes, almacenCorrientes } from './personas-tiendas.mjs';
import { P as PR } from './catalogo-31.mjs';
import { O, T, tel, css } from './catalogo-29.mjs';
import { insig, G as GM } from './marcas.mjs';
import { ICN as ICT } from './catalogo-39.mjs';
import { N as N32 } from './catalogo-32.mjs';
import { IC as ICM } from './catalogo-30.mjs';
import { kirkallpa } from './catalogo-2.mjs';
import { puma } from './puma-muestra.mjs';
import { tero, yacare } from './muestra-bichos.mjs';
import { lucerna } from './luciernaga.mjs';
import { kapiyva } from './catalogo-10.mjs';
import { pasacan } from './catalogo-1.mjs';
import { hud, equipoMini } from './catalogo-35.mjs';

const W = '#fbf6ea';
// ---------- Interiores (vista desde arriba, pared del fondo de frente) ----------
const baldosas = (c1, c2) => `${Array.from({ length: 12 }, (_, r) => Array.from({ length: 8 }, (_, c) => `<rect x="${c * 45}" y="${210 + r * 45}" width="45" height="45" fill="${(r + c) % 2 ? c1 : c2}"/>`).join('')).join('')}`;
const tablas = (c1, c2) => `<rect y="210" width="360" height="550" fill="${c1}"/>${Array.from({ length: 14 }, (_, k) => `<path d="M0,${226 + k * 40} L360,${226 + k * 40}" stroke="${c2}" stroke-width="2"/>`).join('')}${Array.from({ length: 30 }, (_, k) => `<path d="M${(k * 97) % 360},${226 + (k % 14) * 40} l0,40" stroke="${c2}" stroke-width="1.4"/>`).join('')}`;
const pared = (c, zocalo) => `<rect y="70" width="360" height="140" fill="${c}"/><rect y="196" width="360" height="14" fill="${zocalo}"/>`;
const persona = (f, x, y, k = .42) => `<g transform="translate(${x} ${y}) scale(${k})">${f()}</g>`;
const mostrador = (x, y, w, c = '#8a5a32') => `<rect x="${x}" y="${y}" width="${w}" height="40" rx="4" fill="${c}" stroke="${O}" stroke-width="2"/><rect x="${x - 4}" y="${y - 8}" width="${w + 8}" height="12" rx="3" fill="#a8743a" stroke="${O}" stroke-width="2"/>`;
const puerta = `<rect x="150" y="736" width="60" height="24" fill="#6a4a2e" stroke="${O}" stroke-width="2"/><rect x="156" y="740" width="48" height="16" fill="#c9a46a"/>`;
const marco = (cont, lugar) => svg('0 0 360 760', `<defs><clipPath id="ti${lugar.length}"><rect width="360" height="760" rx="26"/></clipPath></defs><g clip-path="url(#ti${lugar.length})"><rect width="360" height="760" fill="#3a2414"/>${cont}${puerta}${persona(jugador, 162, 560)}${hud(lugar, 3, 'manana', 'despejado')}${equipoMini}</g>`);
const estante = (x, y, w, cosas) => `<rect x="${x}" y="${y}" width="${w}" height="8" fill="#6a4a2e" stroke="${O}" stroke-width="1.4"/>${cosas}`;
const frascos = (x, y, n, cols) => Array.from({ length: n }, (_, k) => `<rect x="${x + k * 18}" y="${y - 22}" width="13" height="22" rx="3" fill="${cols[k % cols.length]}" stroke="${O}" stroke-width="1.4"/><rect x="${x + k * 18 + 2}" y="${y - 26}" width="9" height="5" fill="#8a5a32" stroke="${O}" stroke-width="1"/>`).join('');
const latas = (x, y, n, cols) => Array.from({ length: n }, (_, k) => `<rect x="${x + k * 20}" y="${y - 18}" width="16" height="18" fill="${cols[k % cols.length]}" stroke="${O}" stroke-width="1.4"/><rect x="${x + k * 20}" y="${y - 12}" width="16" height="5" fill="#fbf6ea" opacity=".6"/>`).join('');
const ventana = (x, y) => `<rect x="${x}" y="${y}" width="54" height="56" fill="#bfe0ec" stroke="#5a3a22" stroke-width="5"/>${[18, 36].map((d) => `<path d="M${x + d},${y} L${x + d},${y + 56}" stroke="#5a3a22" stroke-width="3"/>`).join('')}`;
const tonel = (x, y) => `<ellipse cx="${x}" cy="${y}" rx="22" ry="28" fill="#8a5a32" stroke="${O}" stroke-width="2"/><path d="M${x - 22},${y - 10} L${x + 22},${y - 10} M${x - 22},${y + 10} L${x + 22},${y + 10}" stroke="#4a4644" stroke-width="3"/>`;
const bolsa = (x, y, c = '#e8dcc0') => `<path d="M${x - 18},${y + 22} C${x - 22},${y} ${x - 12},${y - 16} ${x},${y - 18} C${x + 12},${y - 16} ${x + 22},${y} ${x + 18},${y + 22}Z" fill="${c}" stroke="${O}" stroke-width="1.8"/><path d="M${x - 8},${y - 16} L${x + 8},${y - 16}" stroke="#8a5a32" stroke-width="3"/>`;
const ramo = (x, y, c) => `<path d="M${x},${y} L${x},${y + 10}" stroke="#5a3a22" stroke-width="2"/>${[-8, -3, 2, 7].map((d, i) => `<path d="M${x},${y + 10} C${x + d},${y + 22} ${x + d * 1.4},${y + 34} ${x + d * 1.6},${y + 44}" stroke="${c}" stroke-width="${4 - i % 2}" fill="none" stroke-linecap="round"/>`).join('')}`;

// I1: posta. El maestro de posta cura y da acceso al corral.
const posta = marco(`${pared('#efe7d6', '#c9a46a')}${ventana(36, 100)}${ventana(270, 100)}${baldosas('#c8643a', '#b8563a')}
  <g transform="translate(150 88)"><rect width="60" height="108" fill="#5a3a22" stroke="${O}" stroke-width="2"/>${[0, 1, 2, 3].map((k) => `<path d="M6,${16 + k * 24} L54,${16 + k * 24}" stroke="#a8804e" stroke-width="5"/>`).join('')}<path d="M10,8 L10,104 M50,8 L50,104" stroke="#7a5636" stroke-width="4"/></g>
  ${mostrador(40, 300, 280)}${persona(postera, 150, 214)}
  <g transform="translate(40 250)"><ellipse cx="30" cy="40" rx="30" ry="10" fill="#7a8a96" stroke="${O}" stroke-width="2"/><ellipse cx="30" cy="37" rx="24" ry="7" fill="#9fd3ef"/></g>
  ${[[40, 470], [250, 470]].map(([x, y]) => `<rect x="${x}" y="${y}" width="70" height="20" rx="4" fill="#8a5a32" stroke="${O}" stroke-width="2"/><rect x="${x + 6}" y="${y + 20}" width="6" height="14" fill="#6a4a2e"/><rect x="${x + 58}" y="${y + 20}" width="6" height="14" fill="#6a4a2e"/>`).join('')}`, 'Posta de Cerrillos');

// I2: almacén de ramos generales. Pulpero.
const pizarron = `<g transform="translate(236 92)"><rect width="104" height="80" fill="#2f3a32" stroke="#8a5a32" stroke-width="6"/>${[[16, 20], [16, 44]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="7" fill="none" stroke="#e8e4dc" stroke-width="2"/><path d="M${x + 14},${y} L${x + 50},${y}" stroke="#e8e4dc" stroke-width="2" stroke-dasharray="4 3"/>`).join('')}<circle cx="16" cy="66" r="5" fill="none" stroke="#e8e4dc" stroke-width="2"/><circle cx="30" cy="66" r="5" fill="none" stroke="#e8e4dc" stroke-width="2"/></g>`;
const almacen = marco(`${pared('#e8d8b4', '#8a5a32')}${estante(16, 120, 200, latas(22, 120, 9, ['#c8562a', '#2f6a8a', '#e8c23a']))}${estante(16, 170, 200, frascos(22, 170, 11, ['#e8a23a', '#7aaa4e', '#c8a07a']))}${pizarron}${tablas('#b8946a', '#a8845a')}
  ${mostrador(40, 300, 280, '#7a4a2a')}${persona(pulpero, 150, 214)}${tonel(60, 440)}${tonel(110, 452)}${bolsa(270, 440)}${bolsa(306, 452, '#d8c8a0')}${bolsa(286, 470)}`, 'Almacén de Cerrillos');

// I3: rancho de la curandera. Yuyos colgados, frascos y sahumerio.
const curand = marco(`${pared('#c9a07a', '#8a5a32')}<path d="M0,96 L360,96" stroke="#5a3a22" stroke-width="5"/>${[30, 70, 110, 250, 290, 330].map((x, i) => ramo(x, 96, ['#6a9a4a', '#a8b85a', '#7a8a3a'][i % 3])).join('')}${estante(140, 170, 80, frascos(146, 170, 4, ['#a86aa0', '#7aaa4e', '#e8a23a']))}${tablas('#a8845a', '#98744a')}
  ${mostrador(80, 310, 200, '#6a4a2e')}${persona(curandera, 150, 224)}<g transform="translate(250 290)"><path d="M-14,10 L14,10 C12,20 6,24 0,24 C-6,24 -12,20 -14,10Z" fill="#b8643a" stroke="${O}" stroke-width="1.8"/><path d="M-4,8 C-8,0 0,-6 -4,-14 M4,8 C0,0 8,-6 4,-16" stroke="#b8b0a4" stroke-width="2" fill="none" stroke-linecap="round"/></g>
  <g transform="translate(60 440)"><rect width="240" height="70" rx="10" fill="#c8562a" stroke="${O}" stroke-width="2"/>${['#e8a23a', '#2f7d5b', '#1f1a18', '#e8a23a'].map((c, k) => `<rect y="${10 + k * 14}" width="240" height="6" fill="${c}"/>`).join('')}</g>`, 'Rancho de la curandera');

// ---------- Íconos de tipo (cuadrado redondeado: las marcas son redondas) ----------
