  Flora: `<path d="M13,35 C13,20 22,12 36,12 C36,26 28,35 13,35Z" fill="${W}" stroke="${O}" stroke-width="2"/><path d="M13,35 C20,28 26,22 32,16" stroke="${O}" stroke-width="1.8" fill="none"/>`,
  Tierra: `<path d="M8,34 C12,22 20,16 26,18 C32,14 38,22 40,34Z" fill="${W}" stroke="${O}" stroke-width="2" stroke-linejoin="round"/><path d="M13,28 L35,28" stroke="${O}" stroke-width="1.6"/>`,
  Roca: `<path d="M10,34 L14,24 L22,20 L28,26 L26,34Z" fill="${W}" stroke="${O}" stroke-width="2" stroke-linejoin="round"/><path d="M24,34 L28,22 L36,18 L40,26 L38,34Z" fill="${W}" stroke="${O}" stroke-width="2" stroke-linejoin="round"/>`,
