  Rayo: `<path d="M27,8 L15,26 L23,26 L19,40 L33,20 L25,20Z" fill="${W}" stroke="${O}" stroke-width="2" stroke-linejoin="round"/>`,
  Hielo: `<path d="M10,12 L38,12" stroke="${W}" stroke-width="4" stroke-linecap="round"/>${[[14, 26], [22, 36], [30, 30], [36, 22]].map(([x, y]) => `<path d="M${x - 3},13 L${x},${y} L${x + 3},13Z" fill="${W}" stroke="${O}" stroke-width="1.6" stroke-linejoin="round"/>`).join('')}`,
  Veneno: `<path d="M9,26 C9,14 39,14 39,26Z" fill="${W}" stroke="${O}" stroke-width="2" stroke-linejoin="round"/><path d="M19,26 L19,38 C19,40 29,40 29,38 L29,26" fill="${W}" stroke="${O}" stroke-width="2"/><circle cx="18" cy="20" r="2.6" fill="${COLOR_TIPO.Veneno}"/><circle cx="29" cy="19" r="2" fill="${COLOR_TIPO.Veneno}"/><circle cx="25" cy="23" r="1.6" fill="${COLOR_TIPO.Veneno}"/>`,
  Mito: `<path d="M24,9 L28,19 L39,19 L30,26 L33,37 L24,30 L15,37 L18,26 L9,19 L20,19Z" fill="${W}" stroke="${O}" stroke-width="2" stroke-linejoin="round"/>`,
